import {SPOTIFY_HOME,parseSpotify} from './spotify-auth.js';
import {$,$$,esc,openForm,field,confirmAction,toast} from './ui.js';
import {uid} from './storage.js';
import {lookupSpotifyItem,playlistEmbedURL,playlistReference,playlistReadError} from './spotify-playlists.js';
import {icon} from './icons.js';
const spotifyURL=uri=>{try{return parseSpotify(uri).url;}catch{return 'https://open.spotify.com/';}};
export const safeSpotifyImage=url=>{try{const u=new URL(url);return u.protocol==='https:'&&['i.scdn.co','mosaic.scdn.co','image-cdn-ak.spotifycdn.com','image-cdn-fa.spotifycdn.com'].includes(u.hostname)?u.href:'';}catch{return '';}};
const cover=item=>safeSpotifyImage(item.album?.images?.[0]?.url||item.images?.[0]?.url);
export class SpotifyUI{
  constructor(ctx){this.ctx=ctx;this.player=ctx.engine.spotify;this.playlists=[];this.player.addEventListener('change',()=>this.updateStatus());
    $('#spotifyConnection').onclick=event=>this.busy(event.currentTarget,async()=>{if(!this.player.auth.connected){this.ctx.commit();if(location.origin!==new URL(SPOTIFY_HOME).origin){location.assign(SPOTIFY_HOME);return;}location.assign(await this.player.auth.begin());return;}this.player.activate();if(!this.player.deviceId){await this.player.prepare();toast('Spotify pronto. Lembre de ativar a sessão particular no aplicativo.');}else this.open();});
    $('#spotifySidebarSettings').onclick=()=>this.open();this.updateStatus();
  }
  updateStatus(){const connection=$('#spotifyConnection');if(connection){connection.innerHTML='<img src="assets/spotify-icon.png" alt="" width="18" height="18"><span>'+(!this.player.auth.connected?'Conectar Spotify':this.player.deviceId?'Spotify pronto':'Ativar player Spotify')+'</span>';$('#spotifyPrivateReminder').hidden=!this.player.auth.connected;}const status=$('#spotifyStatus');if(!status)return;status.textContent=this.player.lastError||(this.player.deviceId?'Player pronto. Escolha uma música ou playlist.':this.player.auth.connected?'Conta conectada neste navegador. Ative o player na lateral antes da sessão.':'Conecte sua conta Premium para acessar suas playlists.');}
  open(){const settings=this.ctx.state().settings,connected=this.player.auth.connected,canonical=location.origin===new URL(SPOTIFY_HOME).origin;
    openForm({title:'Spotify · sua trilha',submit:'Salvar ajustes',wide:true,body:`<section class="spotify-account"><img src="assets/spotify-icon.png" alt="Spotify" width="32" height="32"><div><strong>Spotify Premium</strong><p id="spotifyStatus" role="status"></p></div></section><div class="spotify-tools">${!canonical?`<a class="btn primary" href="${SPOTIFY_HOME}">Abrir CRIS para conectar Spotify</a>`:connected?'<button type="button" class="btn outline" id="spotifyLoadPlaylists">Minhas playlists</button><button type="button" class="btn outline" id="spotifyAddLink">Adicionar link</button><button type="button" class="btn outline" id="spotifyCheckPrivate">Conferir sessão particular</button><button type="button" class="btn subtle" id="spotifyDisconnect">Desconectar</button>':'<p class="form-hint">Conecte o Spotify pelo botão na lateral do Director.</p>'}</div><p class="form-hint">A conexão fica lembrada neste navegador. A música usa o player oficial Spotify; volume até 100%, sem amplificação. Entrada e saída usam o volume do player oficial, sem sobrepor duas músicas. Os controles de reprodução ficam na barra inferior do CRIS.</p><section class="spotify-preferences"><h3>Transições suaves</h3><div class="form-grid">${field('Fade de entrada / play (s)','spotifyFadeIn',settings.spotifyFadeIn,'type="number" min="0" max="30" step="0.1" required')}${field('Fade de saída / pausa (s)','spotifyFadeOut',settings.spotifyFadeOut,'type="number" min="0" max="30" step="0.1" required')}</div><p class="form-hint">Também usados nas setas anterior/próxima. Cenas e cues podem definir seus próprios tempos. 0 faz a ação imediatamente. Recomeçar e mover a barra de progresso também usam estes fades. Parar tudo usa o fade global.</p></section><section class="spotify-private"><h3>Sessão particular</h3><p class="form-hint">Antes da mesa, ative Sessão particular no aplicativo Spotify, pelo menu da sua foto de perfil no computador. A configuração vale para a conta e termina após 6 horas ou ao reiniciar o app. O CRIS pode consultar o estado, mas não ativá-la automaticamente.</p><p id="spotifyPrivateStatus" class="form-hint" role="status">Estado ainda não conferido para o player CRIS.</p><a href="https://support.spotify.com/br-pt/article/private-listening/" target="_blank" rel="noopener">Ver orientação do Spotify</a></section><div id="spotifyLists" class="spotify-lists"></div><p class="form-hint">Você autoriza leitura de playlists e controle da reprodução. O CRIS não altera suas playlists no Spotify. <a href="spotify-privacy.html" target="_blank" rel="noopener">Como usamos os dados</a> · <a href="https://www.spotify.com/account/apps/" target="_blank" rel="noopener">Gerenciar acesso no Spotify</a></p>`,onReady:root=>{
      this.updateStatus();
      $('#spotifyConnect',root)?.addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;try{location.assign(await this.player.auth.begin());}catch(error){button.disabled=false;toast(error.message,true);}});
      $('#spotifyPrepare',root)?.addEventListener('click',event=>this.busy(event.currentTarget,async()=>{this.player.activate();await this.player.prepare();toast('Player pronto. Agora escolha sua música.');}));
      $('#spotifyLoadPlaylists',root)?.addEventListener('click',event=>this.busy(event.currentTarget,()=>this.loadPlaylists(root)));
      $('#spotifyCheckPrivate',root)?.addEventListener('click',event=>this.busy(event.currentTarget,async()=>{const status=await this.player.privateSession();$('#spotifyPrivateStatus',root).textContent=status===true?'O Spotify confirmou sessão particular neste player agora.':status===false?'Sessão particular desativada neste player. Ative no aplicativo Spotify e confira novamente.':'O Spotify não confirmou o estado deste player. Prepare o player CRIS, reproduza uma faixa e confira novamente.';}));
      $('#spotifyAddLink',root)?.addEventListener('click',()=>this.addLink());
      $('#spotifyDisconnect',root)?.addEventListener('click',()=>confirmAction('Desconectar Spotify?', 'A autorização será removida deste navegador. As músicas e playlists da sua biblioteca ficam guardadas na sua conta CRIS.',async()=>{
        if(this.ctx.engine.musicAsset?.provider==='spotify')await this.ctx.engine.stopMusic(0);
        this.player.disconnect();
        this.playlists=[];this.ctx.commit();toast('Spotify desconectado neste navegador.');
      },'Desconectar'));
    },onSubmit:form=>{for(const key of ['spotifyFadeIn','spotifyFadeOut']){const value=Number(form.get(key));if(!Number.isFinite(value)||value<0||value>30)throw Error('Use fades de 0 a 30 segundos.');this.ctx.state().settings[key]=value;}this.playlists=[];this.ctx.commit();toast('Transições Spotify salvas.');}});
  }
  async busy(button,callback){button.disabled=true;try{await callback();}catch(error){toast(error.message,true);}finally{if(button.isConnected)button.disabled=false;this.updateStatus();}}
  addItem(item,type){
    const parsed=parseSpotify(item.uri||`spotify:${type}:${item.id}`),state=this.ctx.state();let asset=state.audioAssets.find(a=>a.provider==='spotify'&&a.spotifyUri===parsed.uri);
    const values={name:item.name||'Spotify',kind:'music',provider:'spotify',spotifyUri:parsed.uri,url:parsed.url,tags:'Spotify',cover:cover(item),artists:(item.artists||[]).map(a=>a.name).join(', '),duration:item.duration_ms?item.duration_ms/1000:undefined,shuffle:parsed.type==='playlist',spotifyCount:Number.isInteger(item.items?.total??item.tracks?.total)?(item.items?.total??item.tracks?.total):undefined};
    if(item.metadataUnavailable)values.metadataUnavailable=true;else values.metadataUnavailable=false;
    if(asset)Object.assign(asset,values);else{asset={id:uid('asset'),...values};state.audioAssets.push(asset);}this.ctx.commit();return asset;
  }
  async loadPlaylists(root){
    const lists=$('#spotifyLists',root);lists.textContent='Buscando suas playlists…';
    try{this.playlists=(await this.player.playlists()).filter(p=>p?.id&&p?.name);if(!root.isConnected)return;
      lists.innerHTML='<h3>Suas playlists no Spotify</h3><p class="form-hint">Adicione a playlist inteira à biblioteca ou abra as faixas para escolher músicas individuais para cues.</p>'+this.playlists.map((p,index)=>`<article class="spotify-item">${cover(p)?`<img src="${esc(cover(p))}" alt="" loading="lazy">`:''}<div><a href="${esc(spotifyURL(p.uri||'spotify:playlist:'+p.id))}" target="_blank" rel="noopener">${esc(p.name)}</a><small>Spotify · ${esc(p.owner?.display_name||'Playlist')}</small></div><button type="button" class="btn outline small" data-spotify-import="${index}">Adicionar</button><button type="button" class="btn subtle small" data-spotify-tracks="${index}">Ver faixas</button></article>`).join('')||'<p>Nenhuma playlist foi disponibilizada pelo Spotify para esta conta.</p>';
      $$('[data-spotify-import]',root).forEach(button=>button.onclick=()=>{this.addItem(this.playlists[+button.dataset.spotifyImport],'playlist');toast('Playlist adicionada à biblioteca.');});
      $$('[data-spotify-tracks]',root).forEach(button=>button.onclick=()=>this.busy(button,()=>this.showTracks(this.playlists[+button.dataset.spotifyTracks],root)));
    }catch(error){if(lists.isConnected)lists.textContent='Não foi possível carregar as playlists. '+error.message;throw error;}
  }
  async showTracks(playlist,root){
    const tracks=await this.player.playlistTracks(playlist.id);if(!root.isConnected)return;
    if(!tracks.length)throw Error('O Spotify não disponibilizou faixas desta playlist. Para listas de terceiros, adicione a playlist inteira ou uma faixa pelo link.');
    let limit=50;const render=()=>{
      const list=$('#spotifyLists',root);list.innerHTML=`<button type="button" class="btn subtle" id="spotifyBack">← Minhas playlists</button><h3>${esc(playlist.name)}</h3><p class="form-hint">${tracks.length} faixas disponíveis · adicione à biblioteca para usar em cenas e cues.</p>`+tracks.slice(0,limit).map((t,i)=>`<article class="spotify-item">${cover(t)?`<img src="${esc(cover(t))}" alt="" loading="lazy">`:''}<div><a href="${esc(spotifyURL(t.uri))}" target="_blank" rel="noopener">${esc(t.name)}</a><small>Spotify · ${esc((t.artists||[]).map(a=>a.name).join(', '))}</small></div><button type="button" class="btn outline small" data-spotify-track-add="${i}">Adicionar</button><button type="button" class="btn primary small" data-spotify-track-play="${i}">Ouvir</button></article>`).join('')+(limit<tracks.length?'<button type="button" class="btn outline" id="spotifyMore">Mostrar mais</button>':'');
      $('#spotifyBack',root).onclick=()=>this.loadPlaylists(root).catch(error=>toast(error.message,true));$('#spotifyMore',root)?.addEventListener('click',()=>{limit+=50;render();});
      $$('[data-spotify-track-add]',root).forEach(button=>button.onclick=()=>{this.addItem(tracks[+button.dataset.spotifyTrackAdd],'track');toast('Música adicionada à biblioteca.');});
      $$('[data-spotify-track-play]',root).forEach(button=>button.onclick=()=>{this.player.activate();this.busy(button,()=>this.ctx.engine.playMusic(this.addItem(tracks[+button.dataset.spotifyTrackPlay],'track')));});
    };render();
  }
  openPlaylist(asset){
    const parsed=parseSpotify(asset.spotifyUri||asset.uri);if(parsed.type!=='playlist')return;
    const source=asset.provider==='spotify'?asset:this.ctx.state().audioAssets.find(a=>a.spotifyUri===parsed.uri);
    const name=asset.name||'Playlist Spotify';let request=0,tracks=[],limit=50;
    openForm({title:name,wide:true,body:`<section class="spotify-playlist-heading"><img src="assets/spotify-icon.png" width="28" height="28" alt="Spotify"><div><span class="section-eyebrow">PLAYLIST SPOTIFY</span><p>Consulte as faixas e escolha o próximo momento da mesa.</p></div></section><div class="spotify-playlist-tools"><button type="button" class="btn primary" id="inspectSpotifyPlay">${icon('play')} Reproduzir playlist no CRIS</button><button type="button" class="btn outline" id="inspectSpotifyReload">Atualizar faixas</button><button type="button" class="btn outline" id="inspectSpotifyOfficial">Painel oficial</button><a class="btn subtle" href="${parsed.url}" target="_blank" rel="noopener">Abrir no Spotify ↗</a></div><p class="form-hint">O botão de play e as faixas abaixo usam o player e os fades do CRIS. O painel oficial tem controles próprios.</p><p id="inspectSpotifyStatus" class="spotify-inspect-status" role="status">Consultando faixas…</p><label class="search-field spotify-playlist-search" hidden>${icon('search')}<input type="search" id="inspectSpotifySearch" placeholder="Buscar música ou artista…" aria-label="Buscar músicas desta playlist"></label><div id="inspectSpotifyTracks" class="spotify-inspect-tracks"></div><section id="inspectSpotifyEmbed" hidden></section>`,onReady:root=>{
      const status=$('#inspectSpotifyStatus',root),list=$('#inspectSpotifyTracks',root),search=$('#inspectSpotifySearch',root),official=$('#inspectSpotifyEmbed',root);
      const modal=$('#appDialog'),alive=()=>status.isConnected&&$('#inspectSpotifyStatus',root)===status&&modal.open;
      modal.addEventListener('close',function cleanup(){if(!modal.open||!official.isConnected){official.replaceChildren();request++;modal.removeEventListener('close',cleanup);}});
      const render=()=>{const term=search.value.trim().toLocaleLowerCase(),filtered=tracks.filter(t=>(t.name+' '+(t.artists||[]).map(a=>a.name).join(' ')).toLocaleLowerCase().includes(term));
        list.innerHTML=filtered.slice(0,limit).map(t=>{const index=tracks.indexOf(t);return `<article class="spotify-item">${cover(t)?`<img src="${esc(cover(t))}" alt="" loading="lazy">`:''}<div><a href="${esc(spotifyURL(t.uri))}" target="_blank" rel="noopener">${esc(t.name)}</a><small>${esc((t.artists||[]).map(a=>a.name).join(', '))}</small></div><button type="button" class="btn primary small" data-inspect-play="${index}">Tocar</button><button type="button" class="btn outline small" data-inspect-add="${index}" title="Adicionar faixa à biblioteca para cenas e cues">Adicionar</button></article>`;}).join('')+(limit<filtered.length?'<button type="button" class="btn outline full" id="inspectSpotifyMore">Mostrar mais músicas</button>':'')+(tracks.length&&!filtered.length?'<p class="empty-small">Nenhuma música com esse nome ou artista.</p>':'');
        $('#inspectSpotifyMore',root)?.addEventListener('click',()=>{limit+=50;render();});
        $$('[data-inspect-play]',root).forEach(b=>b.onclick=()=>this.busy(b,async()=>{const track=tracks[+b.dataset.inspectPlay];this.player.activate();if(source)await this.ctx.engine.playMusic(source,{selectedUri:track.uri});else await this.ctx.engine.playMusic(this.addItem(track,'track'));}));
        $$('[data-inspect-add]',root).forEach(b=>b.onclick=()=>{this.addItem(tracks[+b.dataset.inspectAdd],'track');toast('Faixa adicionada à biblioteca. Você pode usá-la em cenas e cues.');});
      };
      const load=async()=>{const generation=++request;status.textContent='Consultando faixas…';try{const items=await this.player.playlistTracks(parsed.id);if(!alive()||generation!==request)return;tracks=items;search.parentElement.hidden=!tracks.length;limit=50;status.textContent=tracks.length?`${tracks.length} músicas disponíveis para consulta.`:'O Spotify não disponibilizou faixas para consulta. Use o painel oficial para conferir a playlist.';render();}catch(error){if(alive()&&generation===request){status.textContent=playlistReadError(error);}}};
      search.oninput=()=>{limit=50;render();};$('#inspectSpotifyReload',root).onclick=event=>this.busy(event.currentTarget,load);
      $('#inspectSpotifyPlay',root).onclick=event=>this.busy(event.currentTarget,async()=>{this.player.activate();const target=source||this.addItem({uri:parsed.uri,name},'playlist');await this.ctx.engine.playMusic(target);});
      $('#inspectSpotifyOfficial',root).onclick=event=>{official.hidden=!official.hidden;event.currentTarget.setAttribute('aria-expanded',String(!official.hidden));official.innerHTML=official.hidden?'':`<p class="form-hint">Painel oficial Spotify. A disponibilidade das faixas e os controles deste painel são definidos pelo Spotify; use o play do CRIS para manter seus fades.</p><iframe title="Playlist ${esc(name)} no Spotify" src="${playlistEmbedURL(parsed.uri)}" width="100%" height="452" frameborder="0" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"></iframe>`;};
      load();
    }});
  }
  addRestrictedPlaylist(parsed){openForm({title:'Adicionar playlist pelo link',submit:'Guardar playlist',body:`<p class="dialog-description">O Spotify não disponibilizou os dados desta playlist para o CRIS. Podemos guardar o link com um nome escolhido por você. A reprodução depende do acesso que o Spotify permitir à sua conta.</p><a class="spotify-source-link" href="${parsed.url}" target="_blank" rel="noopener">Conferir playlist no Spotify ↗</a>${field('Nome na biblioteca','name','','required maxlength="120" placeholder="Ex.: Café de Paris"')}<p class="form-hint">Após adicionar, use Ver faixas → Painel oficial para consultar a playlist quando a lista não estiver disponível ao CRIS.</p>`,onSubmit:form=>{this.addItem(playlistReference(parsed.uri,form.get('name')),'playlist');toast('Playlist guardada pelo link.');}});}
  addLink(){openForm({title:'Adicionar do Spotify',submit:'Adicionar à biblioteca',body:field('Link de música ou playlist','url','','type="url" required placeholder="https://open.spotify.com/track/…"')+'<p class="form-hint">Consultaremos nome e capa. Se o Spotify restringir a consulta de uma playlist, você poderá guardá-la pelo link e escolher um nome.</p>',onSubmit:async form=>{const result=await lookupSpotifyItem(this.player,form.get('url'));if(result.limited)return ()=>this.addRestrictedPlaylist(result.parsed);this.addItem(result.item,result.parsed.type);toast('Spotify adicionado à biblioteca.');}});}
}
